// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // The reference contract's owner() returns _owner (set to address(this) in constructor)
        // The buggy contract's owner() returns address(0)
        // When addReward is called, it uses onlyOwner modifier which calls _checkOwner()
        // _checkOwner() checks if owner() == _msgSender()
        // In the reference: owner() returns address(this), msg.sender is address(this) -> passes
        // In the buggy: owner() returns address(0), msg.sender is address(this) -> fails (require statement reverts)

        // Try to call addReward - should succeed on reference, revert on buggy
        bool ok;
        try c.addReward(address(0x1234567890123456789012345678901234567890)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract should succeed (ok = true), the buggy should fail (ok = false)
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Use the owner (address(this)) to call addReward
        address rewardToken = address(1);
        c.addReward(rewardToken);
        // After call, rewardTokens array should have length 1 in both; but the difference is transferOwnership?
        // Actually the difference stated: after addReward, value of state variable transferOwnership differs.
        // transferOwnership is not a state variable -- it's a function. So we interpret as: owner() differs?
        // Wait -- the problem says: "the value of state variable `transferOwnership` differs". But there is no such state variable.
        // The only state variable that relates to ownership is `_owner` which is private. Its getter is `owner()`.
        // So we assert over `c.owner()`. In reference, owner is unchanged (address(this)).
        // In bug, the modifier is removed so onlyOwner doesn't check -- but the addReward call still succeeds.
        // The difference is that in bug, addReward can be called by non-owner, but here caller is owner so both succeed.
        // The divergence must come from something else. Let's check: the modifier onlyOwner is replaced with _;
        // That means any caller can call addReward, but also other onlyOwner functions become permissionless.
        // One concrete divergence: transferOwnership (the function) can be called by anyone in bug.
        // Let's make a scenario: after addReward, a non-owner calls transferOwnership.
        // In reference, it reverts; in bug, it succeeds, changing owner.
        address nonOwner = address(0x123);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", nonOwner));
        // Now check owner
        bool diverges = (c.owner() == nonOwner);
        // In reference, the call reverts (ok=false), owner stays address(this).
        // In bug, the call succeeds (ok=true), owner becomes nonOwner.
        // So we assert that the reference satisfies: owner is NOT nonOwner.
        assertTrue(!diverges, "Bug: owner changed after unauthorized transferOwnership");
    }
}

