pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // The constructor sets rewardDistributor to address(this) (= the test contract)
        // In the reference, setRewardDistributor works, but in the buggy contract it reverts.
        // We call addReward (just to have a state change that doesn't affect rewardDistributor)
        c.addReward(address(0xdead));
        // Now assert that rewardDistributor is still the original address (the deployer).
        // In the reference, setRewardDistributor could have changed it, but we never called it.
        // In the buggy version, even if we tried, it would revert; but since we didn't call it, both are same.
        // To observe divergence, we first call setRewardDistributor with a different address.
        // The reference changes the state, the buggy reverts leaving it unchanged.
        // We catch the call and then read the getter.
        bool ok;
        vm.prank(address(this));
        try c.setRewardDistributor(address(0x1234)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == true, rewardDistributor == 0x1234; Bug: ok == false, rewardDistributor == address(this)
        assertTrue(c.rewardDistributor() == address(0x1234));
    }
}

