pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a mock token for staking
        address mockToken = address(0x1234);
        // Make it return true on transferFrom
        vm.mockCall(mockToken, abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)"))), abi.encode(true));
        vm.mockCall(mockToken, abi.encodeWithSelector(bytes4(keccak256("allowance(address,address)"))), abi.encode(0));
        // Set balance of msg.sender for stakeAll
        vm.mockCall(mockToken, abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)"))), abi.encode(100));
        // Set stakingToken in constructor to mockToken
        // But constructor is called in setUp with address(this) and address(this), we need to change it
        // Actually the constructor sets stakingToken = IERC20(_stakingToken), which is address(this) from setUp
        // So we need to mock address(this) as the token
        address stakingToken = address(this);
        // Deploy C with stakingToken = address(this) and distributor = address(this)
        c = new C(stakingToken, address(this));
        // Now mock address(this) as ERC20
        vm.mockCall(stakingToken, abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)"))), abi.encode(true));
        vm.mockCall(stakingToken, abi.encodeWithSelector(bytes4(keccak256("allowance(address,address)"))), abi.encode(0));
        vm.mockCall(stakingToken, abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)"))), abi.encode(100));

        // Stake 100 tokens
        c.stake(100);
        uint256 supplyAfterStake = c.totalSupply();
        assertEq(supplyAfterStake, 100, "totalSupply should be 100 after stake");

        // Now call addReward with a dummy reward token
        address dummyReward = address(0xDead);
        c.addReward(dummyReward);

        // After addReward, totalSupply should still be 100 in reference
        uint256 finalSupply = c.totalSupply();
        assertEq(finalSupply, 100, "totalSupply should remain 100 after addReward");
    }
}

